"OLAYLAR_ORTACAG_ORTADOGU:0705-01-02:0":{"b": ["Velidi I u bë kalif (86/705); në kohën e tij Shteti Umajad arriti kufijtë më të gjerë.", "c848f25f"], "d": ["Velidi I u bë kalif (86/705); në kohën e tij Shteti Umajad arriti kufijtë më të gjerë.", "c848f25f"]},
"OLAYLAR_ORTACAG_ORTADOGU:0711-07-26:0":{"b": ["Tarik b. Zijadi i shkaktoi një disfatë të rëndë ushtrisë vizigote", "73301b6a"], "d": ["Në fund të betejës tetëditore midis dy ushtrive, ushtria vizigote pësoi një disfatë të rëndë (5 sheval 92 / 26 korrik 711); vendi i betejës është bregu i Guadalete-s ose Barbate-s. Tregohet se Tariku për një kohë të shkurtër pushtoi Malagën, Elvirën, Kordobën dhe Toledon.", "12d78ad9"]},
"OLAYLAR_ORTACAG_ORTADOGU:0712-06-20:0":{"b": ["Përballë Muhamed b. Kasimit vdiq raxha i Sindit Dahiri; u pushtuan Ruri (Arur, Aror), Brahmanabadi dhe Multani", "bccf3c4f"], "d": ["Sundimtari i Sindit Dahiri, që luftonte me komandantin umajad Muhamed b. Kasim, vdiq më 10 ramazan 93 / 20 qershor 712; pas kësaj beteje u pushtuan Ruri (Arur, Aror), Brahmanabadi dhe Multani dhe i gjithë Sindi kaloi në duart e Umajadëve.", "e213eabd"]},
"OLAYLAR_ORTACAG_ORTADOGU:0724-01-01:0":{"b": ["Hisham b. Abdulmeliku u bë kalif (105/724); sundoi deri në 743.", "6288b8a9"], "d": ["Hisham b. Abdulmeliku u bë kalif (105/724); sundoi deri në 743.", "6288b8a9"]},
"OLAYLAR_ORTACAG_ORTADOGU:0732-03-03:0":{"b": ["Ushtria umajade luftoi kundër frankëve pranë Poitiers-it (Tours) (114/732).", "97262cdf"], "d": ["Ushtria umajade luftoi kundër frankëve pranë Poitiers-it (Tours) (114/732).", "97262cdf"]},
"OLAYLAR_ORTACAG_ORTADOGU:0744-12-07:0":{"b": ["Mervani II u shpall kalif", "f51a800a"], "d": ["Të pranishmit atje e shpallën Mervanin kalif (26 safer 127 / 7 dhjetor 744); filloi periudha e kalifit të fundit umajad.", "1bc682b5"]},
"OLAYLAR_ORTACAG_ORTADOGU:0746-01-01:0":{"b": ["Mervani II e nënshtroi Sirinë; i shkatërroi muret e Homsit, Baalbekut, Damaskut dhe Jerusalemit", "468a2d97"], "d": ["Mervani, që për të parandaluar kryengritje të mundshme shkatërroi muret e qyteteve siriane, e nënshtroi Sirinë në verën e 128 (746).", "afc53641"]},
"OLAYLAR_ORTACAG_ORTADOGU:0746-09-22:0":{"b": ["Udhëheqësi haridxhit (ibadit) Talibul-Hak, pas Hadramautit, ua mori Sanan (San‘a) Umajadëve (129/746)", "d56ff983"], "d": ["Abdullah b. Jahja el-Hadrami (Talibul-Hak) u ngrit kundër Umajadëve me mbështetjen e ibaditëve të Omanit dhe u shpall kalif; pas Hadramautit pushtoi Sanan (San‘a). Pastaj marshoi mbi Mekën dhe Medinën, u mund nga forcat e Mervanit II dhe u vra pranë Sanasë (130/748).", "a2697365"]},
"OLAYLAR_ORTACAG_ORTADOGU:0747-01-01:0":{"b": ["Nën udhëheqjen e Ebu Muslimit, në Horasan filloi haptazi revolucioni abasid (129/747).", "92a5194c"], "d": ["Nën udhëheqjen e Ebu Muslimit, në Horasan filloi haptazi revolucioni abasid (129/747).", "92a5194c"]},
