"OLAYLAR_ORTACAG_ORTADOGU:0838-01-01:0":{"b": ["Mu'tasimi hyri në Anadoll, rrethoi dhe pushtoi Ammurijen (Amorionin)", "63534eea"], "d": ["Kalifi Mu'tasim hyri në Anadoll në 838 me një ushtri të madhe; duke marshuar nëpër Ankara, rrethoi dhe pushtoi Ammurijen, nga qytetet e mëdha të Anadollit pranë Afionit.", "530472b7"]},
"OLAYLAR_ORTACAG_ORTADOGU:0868-09-15:0":{"b": ["Ahmed b. Tuluni hyri në Egjipt si zëvendësguvernator; u hodhën themelet e Tulunidëve", "7bfc6989"], "d": ["Ahmed b. Tuluni hyri në Egjipt si zëvendësguvernator; u hodhën themelet e Tulunidëve", "7bfc6989"]},
