"OLAYLAR_ORTACAG_ORTADOGU:1285-01-01:0":{"b": ["Kalavuni mori kështjellën Merkab (Margat) të Hospitalierëve dhe e zhduku këtë forcë kryqtare; ra fortifikimi i fundit i madh kryqtar në afërsi të Kontesë së Tripolit (684/1285).", "722b884f"], "d": ["Kalavuni mori kështjellën Merkab (Margat) të Hospitalierëve dhe e zhduku këtë forcë kryqtare; ra fortifikimi i fundit i madh kryqtar në afërsi të Kontesë së Tripolit (684/1285).", "722b884f"]},
"OLAYLAR_ORTACAG_ORTADOGU:1287-01-01:0":{"b": ["Vdiq konti Boemund VII; grindja për trashëgimi midis motrës së tij Luçia dhe komunës së qytetit të mbështetur nga gjenovezët e dobësoi kontenë dhe i dha mundësi Kalavunit.", "e68819ba"], "d": ["Vdiq konti Boemund VII; grindja për trashëgimi midis motrës së tij Luçia dhe komunës së qytetit të mbështetur nga gjenovezët e dobësoi kontenë dhe i dha mundësi Kalavunit.", "e68819ba"]},
